+package com.example.data;
+
+import org.springframework.stereotype.Service;
+
+import java.time.Instant;
+import java.util.ArrayList;
+import java.util.List;
+
+@Service
+public class ContactMessageService {
+
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    public synchronized void send(String name, String email, String phone, String message) {
+        messages.add(0, new ContactMessage(name, email, phone, message, Instant.now()));
+    }
+
+    public synchronized List<ContactMessage> findAll() {
+        return List.copyOf(messages);
+    }
+}
